// B7 - Final Check + Fallback
// Validates the assembled result before sending to FastAPI

const BANNED_PHRASES = [
  "you have", "diagnos", "medication",
  "stop the exercise", "injury", "damaged"
];

const input = $input.first().json;
const coachingOutput = input.coaching_output || "";
const ruleFlags = input.rule_flags || [];
const metrics = input.metrics || {};
const sessionId = input.session_id || 0;
const assessmentSummary = input.assessment_summary || "";
const progressSummary = input.progress_summary || "";
const qualityBand = input.quality_band || "unknown";
const trend = input.trend || "unknown";

const errors = [];

// Check 1 — coaching output exists
if (!coachingOutput || coachingOutput.trim() === "") {
  errors.push("coaching_output is empty");
}

// Check 2 — banned phrases in coaching message
for (const phrase of BANNED_PHRASES) {
  if (coachingOutput.toLowerCase().includes(phrase.toLowerCase())) {
    errors.push("banned phrase found: " + phrase);
  }
}

// Check 3 — banned phrases in physio summaries
for (const phrase of BANNED_PHRASES) {
  if (assessmentSummary.toLowerCase().includes(phrase.toLowerCase())) {
    errors.push("banned phrase in assessment_summary: " + phrase);
  }
  if (progressSummary.toLowerCase().includes(phrase.toLowerCase())) {
    errors.push("banned phrase in progress_summary: " + phrase);
  }
}

// Check 4 — no specific numbers in coaching message
const numberPattern = /\b\d+(\.\d+)?\s*(degrees?|°|%|reps?|repetitions?)\b/i;
if (numberPattern.test(coachingOutput)) {
  errors.push("coaching message contains specific numbers");
}

// Build result
const hasHighFlag = ruleFlags.some(f => f.severity === "high");
const needsFallback = errors.length > 0;

const result = {
  contract_version: "1.0",
  session_id: sessionId,
  metrics: metrics,
  assessment: {
    quality_band: qualityBand,
    summary_for_physio: assessmentSummary
  },
  progress: {
    trend: trend,
    summary_for_physio: progressSummary
  },
  review: {
    needs_physio_attention: hasHighFlag || needsFallback,
    flags: ruleFlags
  },
  coaching: {
    patient_message: needsFallback ? "" : coachingOutput,
    status: needsFallback ? "fallback" : "pending_review"
  },
  llm_status: needsFallback ? "fallback" : "ok",
  validation_errors: errors
};

return [{ json: result }];
